-- Revocable owner consent pins one existing rule revision, bank and exact payee.
CREATE TABLE pt_agent_permissions(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind='bank-rule'),owner_id TEXT NOT NULL,owner_email TEXT NOT NULL,rule_id TEXT NOT NULL REFERENCES pt_bank_rules(id),rule_revision TEXT NOT NULL,bank_account_id TEXT NOT NULL REFERENCES pt_bank_accounts(id),payee TEXT NOT NULL,max_cents INTEGER NOT NULL CHECK(max_cents>0),active INTEGER NOT NULL CHECK(active IN(0,1)),created_at TEXT NOT NULL,revision TEXT NOT NULL);
CREATE TABLE pt_agent_actions(id TEXT PRIMARY KEY,permission_id TEXT NOT NULL REFERENCES pt_agent_permissions(id),permission_revision TEXT NOT NULL,permission_snapshot TEXT NOT NULL CHECK(json_valid(permission_snapshot)),bank_line_id TEXT NOT NULL UNIQUE REFERENCES pt_bank_lines(id),match_id TEXT NOT NULL UNIQUE REFERENCES pt_matches(id),at TEXT NOT NULL,review TEXT CHECK(review IN('correct','changed')),reviewed_by TEXT,reviewed_at TEXT);
CREATE INDEX pt_agent_actions_sample ON pt_agent_actions(permission_id,at,id);
